// Praxis - Banque de questions extraites des modules SimAs existants
// Source : questions deja verifiees et integrees dans chaque module (const questions=[...])
// Regroupees ici uniquement pour permettre le mode Examen Chronometre transversal

const BANQUE_EXAMEN_AS = [

  { module:'Module 01 - Vie quotidienne', q:'Mme Aubert, 86 ans, refuse ce matin que vous lui fassiez sa toilette. Elle dit qu\'elle veut rester au lit. Que faites-vous ?', opts:['Vous insistez — la toilette est obligatoire pour l\'hygiène', 'Vous respectez son refus, lui proposez un débarbouillage minimum, transmettez à l\'IDE et notez dans le dossier', 'Vous revenez dans 10 minutes sans la prévenir', 'Vous appelez la famille pour qu\'ils la convainquent'], rep:1, expl:'Toute personne a le droit de refuser un soin — c\'est la loi. L\'AS respecte ce refus, propose une alternative minimaliste si acceptée, transmet à l\'IDE et trace dans le dossier. Le refus d\'un soin est une information clinique importante (douleur ? dépression ? raison particulière ?).' },
  { module:'Module 01 - Vie quotidienne', q:'Lors de la toilette de M. Bernard, vous réalisez ses soins périnéaux. Dans quel ordre procédez-vous ?', opts:['En premier, c\'est la zone la plus à risque', 'En dernier, avec changement de gants, de l\'avant vers l\'arrière chez la femme', 'En même temps que la toilette du bas du corps, pour gagner du temps', 'N\'importe quand, l\'ordre n\'a pas d\'importance si on change de gants'], rep:1, expl:'Les soins périnéaux se font TOUJOURS en dernier, après tous les autres soins du corps, avec changement de gants obligatoire. Chez la femme, la technique est de l\'avant vers l\'arrière pour éviter la contamination de l\'urètre par les bactéries rectales — risque d\'infection urinaire.' },
  { module:'Module 01 - Vie quotidienne', q:'Pendant le repas de Mme Dupont, elle tousse brusquement après avoir avalé un morceau de viande et sa voix devient gargouillante. Que faites-vous ?', opts:['Vous lui donnez un grand verre d\'eau pour faire passer le morceau', 'Vous arrêtez immédiatement le repas, la penchez légèrement en avant et appelez l\'IDE', 'Vous continuez le repas en surveillant — la toux devrait passer', 'Vous lui donnez le reste du repas en texture mixée'], rep:1, expl:'Toux + voix gargouillante pendant le repas = fausse route. Arrêter immédiatement le repas, incliner légèrement la tête en avant, appeler l\'IDE. JAMAIS donner à boire pour \'faire passer\' — le liquide peut aggraver l\'inhalation. Tracer l\'incident dans le dossier même si la personne se remet.' },
  { module:'Module 01 - Vie quotidienne', q:'En changeant la protection de M. Martin, vous observez des urines très foncées, presque brunes, avec une forte odeur. Que faites-vous ?', opts:['Vous notez dans le dossier et attendez la transmission de 16h', 'Vous lui proposez de boire et signalez à l\'IDE dans la journée si ça ne s\'améliore pas', 'Vous signalez à l\'IDE dans la matinée avec description précise — couleur, odeur, quantité estimée', 'Vous changez la protection et ne dites rien car il a peu bu ce matin'], rep:2, expl:'Urines brun foncé + forte odeur = déshydratation sévère et/ou infection urinaire possible. C\'est à signaler à l\'IDE dans la matinée avec les informations précises. Ne pas attendre — une infection urinaire chez une personne âgée peut dégénérer rapidement en confusion aiguë ou sepsis.' },
  { module:'Module 01 - Vie quotidienne', q:'Qu\'est-ce que le GIR 1 dans la grille AGGIR ?', opts:['La personne la plus autonome', 'La personne qui a une dépendance légère nécessitant une aide ponctuelle', 'La personne totalement dépendante avec des fonctions vitales altérées, nécessitant une présence soignante permanente', 'La personne qui peut se déplacer mais a besoin d\'aide pour la toilette'], rep:2, expl:'GIR 1 = dépendance totale. La personne est alitée, a des troubles mentaux graves, des fonctions vitales altérées. Elle nécessite une présence soignante permanente. C\'est le niveau de dépendance le plus élevé — à l\'opposé du GIR 6 (personne autonome).' },
  { module:'Module 01 - Vie quotidienne', q:'Vous accompagnez Mme Legrand (Alzheimer) lors d\'une activité en salle commune. Elle commence à dire que sa mère va venir la chercher (sa mère est décédée depuis 30 ans). Que faites-vous ?', opts:['Vous lui dites clairement que sa mère est décédée pour la ramener à la réalité', 'Vous entrez doucement dans son monde : \'Ah oui, elle arrive bientôt ?\' et restez présente', 'Vous l\'ignorez et continuez l\'activité', 'Vous appelez l\'IDE car c\'est une hallucination'], rep:1, expl:'Chez une personne atteinte d\'Alzheimer, corriger brutalement ses \'erreurs de réalité\' provoque de l\'angoisse sans bénéfice thérapeutique. La validation (entrer doucement dans son monde avec bienveillance) est l\'approche recommandée. Ce n\'est pas mentir — c\'est accompagner.' },
  { module:'Module 01 - Vie quotidienne', q:'Le projet de vie d\'un résident en EHPAD, c\'est :', opts:['Le plan de soins médical établi par le médecin', 'Un document qui dit qui est la personne au-delà de sa pathologie : habitudes, goûts, histoire de vie, préférences', 'La liste des médicaments et des soins quotidiens', 'Le contrat de séjour signé à l\'entrée'], rep:1, expl:'Le projet de vie est un document centré sur la PERSONNE et non sur la pathologie. Il contient ses habitudes de vie, ses goûts, son histoire, ses valeurs. L\'AS le consulte pour personnaliser l\'accompagnement. Tout changement d\'habitudes est un signe d\'alerte à transmettre à l\'équipe.' },
  { module:'Module 01 - Vie quotidienne', q:'M. Petit, aidant de sa femme, vous dit en larmes lors d\'une visite : \'Je n\'en peux plus, je suis épuisé.\' Quelle est votre réaction ?', opts:['Vous lui dites de tenir bon, sa femme a besoin de lui', 'Vous l\'écoutez avec bienveillance, le valorisez dans son rôle et signalez à l\'IDE ou à l\'assistante sociale pour une orientation vers des dispositifs de répit', 'Vous lui dites que vous ne pouvez pas l\'aider, c\'est le rôle du médecin', 'Vous en parlez aux autres résidents pour sensibiliser'], rep:1, expl:'L\'épuisement de l\'aidant est une situation à risque — pour lui et pour la personne aidée. L\'AS écoute sans juger, valorise le rôle de l\'aidant et signale à l\'IDE ou à l\'assistante sociale. Des dispositifs de répit existent (accueil de jour, hébergement temporaire, plateformes de répit) — orienter vers eux est un acte professionnel.' },
  { module:'Module 01 - Vie quotidienne', q:'Lors de la toilette de M. Durant, vous observez une rougeur persistante au sacrum qui ne blanchit pas à la pression. Quelle est votre action prioritaire ?', opts:['Masser doucement avec de la crème pour activer la circulation', 'Signaler immédiatement à l\'IDE, supprimer l\'appui, ne jamais masser la zone rouge', 'Attendre la fin de la tournée pour en parler à l\'IDE', 'Appliquer un pansement occlusif en attendant l\'IDE'], rep:1, expl:'Rougeur qui ne blanchit pas = escarre stade 1 — le seul stade totalement réversible si on agit immédiatement. L\'AS signale à l\'IDE immédiatement (pas en fin de tournée), supprime l\'appui (repositionnement), et ne masse JAMAIS — le massage aggrave les lésions vasculaires.' },
  { module:'Module 01 - Vie quotidienne', q:'Quelle position est obligatoire pour l\'aide aux repas ?', opts:['Décubitus dorsal à 30° — évite la fatigue', 'Position semi-assise à 45°', 'Position assise à 90° avec tête légèrement fléchie en avant', 'N\'importe quelle position si la personne est à l\'aise'], rep:2, expl:'La position assise à 90° est obligatoire pour prévenir les fausses routes. La tête légèrement fléchie en avant (pas en hyperextension) favorise le mécanisme de déglutition. La position allongée ou même semi-assise à 30-45° augmente le risque d\'inhalation et de reflux gastro-œsophagien.' },
  { module:'Module 03 - Évaluation clinique', q:'Vous mesurez la tension artérielle de Mme Dupont à 85/55 mmHg. Elle dit se sentir étourdie. Que faites-vous ?', opts:['Vous notez la valeur et continuez votre tournée', 'Vous lui dites de se reposer et revenez dans une heure', 'Vous alertez l\'IDE immédiatement avec la valeur, l\'heure et les signes cliniques', 'Vous lui proposez un verre d\'eau et remesurez dans 10 minutes'], rep:2, expl:'85/55 mmHg = hypotension (inférieure à 90/60 mmHg) avec signes cliniques (étourdissements). C\'est une alerte urgente à transmettre à l\'IDE immédiatement avec la valeur exacte, l\'heure de mesure et les symptômes associés.' },
  { module:'Module 03 - Évaluation clinique', q:'M. Bernard (habituellement lucide) est confus ce matin — il ne reconnaît pas l\'AS et dit des choses incohérentes. Que faites-vous ?', opts:['C\'est normal à son âge, vous continuez les soins', 'Vous signalez à l\'IDE car c\'est un changement inhabituel pouvant signaler une urgence', 'Vous attendez la visite médicale du lendemain', 'Vous en parlez à la famille lors de leur prochaine visite'], rep:1, expl:'Une confusion nouvelle chez une personne habituellement lucide est un signe d\'alerte urgent — elle peut indiquer une infection urinaire, une déshydratation, un AVC, une hypoglycémie ou un effet médicamenteux. Signaler à l\'IDE immédiatement, jamais attendre.' },
  { module:'Module 03 - Évaluation clinique', q:'Lors du soin de Mme R. (Alzheimer), vous observez qu\'elle grimace et protège son bras droit à chaque mobilisation. Quelle est la bonne interprétation ?', opts:['Elle fait un caprice — c\'est fréquent avec Alzheimer', 'C\'est un signe comportemental possible de douleur — à signaler à l\'IDE avec description précise', 'Elle est fatiguée — laisser reposer et reprendre plus tard', 'La démence fait qu\'on ne peut pas évaluer la douleur'], rep:1, expl:'Les grimaces et la protection d\'une zone corporelle sont des signes comportementaux de douleur — particulièrement importants chez les personnes qui ne peuvent pas verbaliser leur douleur. L\'AS observe, décrit précisément (zone, type de geste, contexte) et signale à l\'IDE qui utilisera une échelle adaptée (DOLOPLUS ou ALGOPLUS).' },
  { module:'Module 03 - Évaluation clinique', q:'Quelle échelle d\'évaluation de la douleur est adaptée à une personne atteinte de démence sévère ne pouvant pas communiquer ?', opts:['EN (Échelle Numérique) — rapide et efficace', 'EVA (Échelle Visuelle Analogique) — plus précise', 'DOLOPLUS-2 ou ALGOPLUS — basées sur l\'observation comportementale', 'Aucune échelle n\'est fiable chez les personnes démentes'], rep:2, expl:'L\'EN et l\'EVA nécessitent que la personne puisse comprendre et exprimer un chiffre — impossible en cas de démence sévère. DOLOPLUS-2 et ALGOPLUS sont des échelles observationnelles : l\'AS observe les comportements (grimaces, agitation, protection) sans que la personne ait besoin de répondre.' },
  { module:'Module 03 - Évaluation clinique', q:'Vous observez que M. Martin n\'a quasi rien bu depuis ce matin, ses urines sont brun foncé et il est inhabituelement somnolent. Vous suspectez :', opts:['Une simple fatigue due à sa pathologie', 'Une déshydratation — à signaler à l\'IDE dans la journée', 'Une déshydratation potentiellement sévère — à signaler à l\'IDE immédiatement', 'Un problème rénal qui attend la visite médicale'], rep:2, expl:'Urines brun foncé + somnolence inhabituelle + apports hydriques insuffisants = déshydratation sévère possible. Chez la personne âgée, la confusion et la somnolence peuvent précéder le choc hypovolémique. Signalement immédiat à l\'IDE — pas dans la journée.' },
  { module:'Module 03 - Évaluation clinique', q:'Un bilan entrées/sorties est prescrit pour Mme G. À 14h, vous notez qu\'elle a bu 450 mL et produit 180 mL d\'urines depuis 8h. Que faites-vous ?', opts:['C\'est équilibré, rien à signaler', 'Vous notez précisément dans le dossier et signalez à l\'IDE ces valeurs lors de la transmission', 'Vous lui donnez une perfusion pour compenser', 'Vous attendez 20h pour faire le bilan complet avant de signaler'], rep:1, expl:'Le bilan entrées/sorties se note à chaque mesure avec l\'heure précise — pas seulement en fin de journée. Ces données permettent à l\'IDE et au médecin de détecter un déséquilibre précocement. La diurèse de 180 mL en 6h est à la limite basse — à signaler lors de la transmission.' },
  { module:'Module 03 - Évaluation clinique', q:'Vous trouvez Mme Aubert inconsciente dans sa chambre, elle ne répond pas à votre voix ni à votre toucher. Quelle est votre première action ?', opts:['Lui faire la toilette rapidement puis prévenir l\'IDE', 'Appeler à l\'aide et alerter l\'IDE et le 15 immédiatement', 'Prendre ses constantes avant d\'alerter', 'Attendre 5 minutes pour voir si elle reprend conscience'], rep:1, expl:'Une personne inconsciente est une urgence vitale. La première action est d\'appeler à l\'aide et d\'alerter l\'IDE et le 15 — simultanément si possible. On ne perd pas de temps à prendre des constantes ou à attendre. Si elle ne respire pas, on commence la RCP en attendant les secours.' },
  { module:'Module 03 - Évaluation clinique', q:'Vous suspectez un AVC chez M. Bernard qui présente une asymétrie du visage et ne peut plus lever le bras droit. Quelle information est CRUCIALE à noter immédiatement ?', opts:['Sa tension artérielle du matin', 'L\'heure exacte d\'apparition des premiers signes', 'Son dernier repas', 'Son traitement anticoagulant'], rep:1, expl:'L\'heure de début des signes d\'AVC est cruciale pour le traitement : la thrombolyse (traitement dissolvant le caillot) ne peut être administrée que dans les 4h30 suivant le début des symptômes. L\'AS qui note l\'heure exacte contribue directement à sauver la vie et à limiter les séquelles.' },
  { module:'Module 03 - Évaluation clinique', q:'La fréquence respiratoire normale d\'un adulte est de :', opts:['6 à 12 mouvements par minute', '12 à 20 mouvements par minute', '20 à 30 mouvements par minute', 'Peu importe tant que la personne ne se plaint pas'], rep:1, expl:'La fréquence respiratoire normale est de 12 à 20 mouvements par minute. En dessous de 12 (bradypnée) ou au-dessus de 25 (tachypnée), alerter l\'IDE. La mesure se fait discrètement sans prévenir le patient — qui modifie automatiquement sa respiration s\'il sait qu\'on le surveille.' },
  { module:'Module 03 - Évaluation clinique', q:'Lors d\'une crise convulsive, quelle action est INTERDITE ?', opts:['Chronométrer la durée de la crise', 'Protéger la tête avec quelque chose de mou', 'Mettre un objet entre les dents pour éviter qu\'il se morde', 'Libérer l\'espace autour de la personne'], rep:2, expl:'Il ne faut JAMAIS mettre quoi que ce soit dans la bouche d\'une personne en crise convulsive — risque de fracture dentaire, de luxation de mâchoire et de fausse route. Contrairement aux idées reçues, une personne en crise ne peut pas avaler sa langue. Les bonne actions : chronométrer, protéger la tête, libérer l\'espace, appeler l\'IDE.' },
  { module:'Module 04 - Soins adaptés', q:'Lors de la toilette au lit, dans quel ordre réalisez-vous les soins périnéaux ?', opts:['En premier, avant la toilette du corps, car c\'est la zone la plus à risque', 'En dernier, après tous les autres soins, avec changement de gants', 'En même temps que les soins du bas du corps', 'Peu importe l\'ordre si on change de gants'], rep:1, expl:'Les soins périnéaux se réalisent toujours en dernier, après tous les autres soins du corps. Changement de gants obligatoire avant. La technique est de l\'avant vers l\'arrière — jamais l\'inverse — pour éviter la contamination de l\'urètre par les bactéries rectales.' },
  { module:'Module 04 - Soins adaptés', q:'Pour réaliser le soin de bouche d\'un patient inconscient, quelle est la position obligatoire ?', opts:['Décubitus dorsal (sur le dos) pour avoir accès à la bouche', 'Position semi-assise à 45°', 'Décubitus latéral ou tête tournée sur le côté', 'Position assise au bord du lit'], rep:2, expl:'La position latérale (sur le côté) ou tête tournée est OBLIGATOIRE pour un patient inconscient. En décubitus dorsal, tout liquide introduit dans la bouche risque d\'être inhalé dans les poumons (fausse route → pneumonie par inhalation).' },
  { module:'Module 04 - Soins adaptés', q:'M. Dupont refuse de prendre ses médicaments du soir. Que faites-vous ?', opts:['Vous les écrasez et les mettez dans sa compote pour qu\'il les prenne sans le savoir', 'Vous insistez gentiment jusqu\'à ce qu\'il accepte', 'Vous respectez son refus, vous l\'informez l\'IDE immédiatement et tracez dans le dossier', 'Vous attendez la prochaine tournée et réessayez sans prévenir l\'IDE'], rep:2, expl:'Le refus de médicament se respecte — tout patient a le droit de refuser un soin. L\'AS prévient l\'IDE immédiatement qui évaluera la situation et contactera le médecin si nécessaire. Cacher des médicaments dans la nourriture sans prescription constitue une maltraitance.' },
  { module:'Module 04 - Soins adaptés', q:'Lors du change de poche de stomie de Mme Legrand, vous observez que sa stomie est violacée. Que faites-vous ?', opts:['Vous posez la nouvelle poche et notez l\'observation dans le dossier pour l\'IDE', 'Vous stoppez le soin, protégez avec une compresse humide et alertez l\'IDE immédiatement', 'Vous nettoyez plus soigneusement — ça devrait s\'améliorer', 'Vous attendez la prochaine toilette pour voir l\'évolution'], rep:1, expl:'Une stomie violacée ou bleue est un signe d\'insuffisance vasculaire (risque de nécrose). C\'est une urgence. L\'AS stoppe immédiatement le soin, couvre délicatement avec une compresse humide et appelle l\'IDE. Ne jamais poser une nouvelle poche sur une stomie suspecte sans évaluation médicale.' },
  { module:'Module 04 - Soins adaptés', q:'Lors de la toilette de M. Bernard, vous observez une rougeur au niveau du sacrum qui ne blanchit pas à la pression. Votre action prioritaire ?', opts:['Masser doucement avec de la crème hydratante pour activer la circulation', 'Signaler à l\'IDE dans la journée lors de la transmission de 16h', 'Alerter l\'IDE immédiatement, supprimer l\'appui et ne pas masser', 'Attendre le lendemain pour voir si ça disparaît'], rep:2, expl:'Une rougeur qui ne blanchit pas = escarre stade 1. C\'est le seul stade entièrement réversible si on agit immédiatement. L\'AS signale à l\'IDE immédiatement, supprime l\'appui (repositionnement) et ne masse JAMAIS une zone rouge — le massage aggrave les lésions.' },
  { module:'Module 04 - Soins adaptés', q:'Pour repositionner une personne alitée à risque élevé d\'escarre (Braden ≤ 12), quelle est la fréquence recommandée ?', opts:['Toutes les 4 heures', 'Toutes les 2 heures maximum — toutes les heures si risque très élevé', 'Une fois par jour lors de la toilette', 'Uniquement quand la personne se plaint d\'inconfort'], rep:1, expl:'Pour un risque élevé (Braden ≤ 12), le repositionnement doit être effectué toutes les 2 heures maximum, voire toutes les heures. Chaque repositionnement est tracé dans le dossier (feuille de turning). Sans traçabilité, le repositionnement n\'existe pas légalement.' },
  { module:'Module 04 - Soins adaptés', q:'Vous trouvez Mme Aubert décédée dans sa chambre à 6h30 lors de votre tournée. Votre première action ?', opts:['Commencer immédiatement la toilette mortuaire pour la dignité', 'Appeler la famille pour les prévenir avant toute chose', 'Alerter l\'IDE — aucun soin ne peut commencer avant le constat médical', 'Retirer les perfusions et sondes pour préparer la chambre'], rep:2, expl:'Aucun soin post-mortem ne peut commencer avant le constat officiel du décès par un médecin. L\'AS ne constate jamais le décès. Il alerte l\'IDE, ne touche à rien, n\'appelle pas la famille (c\'est le rôle de l\'équipe médicale). C\'est une obligation légale.' },
  { module:'Module 04 - Soins adaptés', q:'Lors de la toilette buccale d\'un patient portant un dentier, comment conserve-t-on le dentier la nuit ?', opts:['Enveloppé dans du papier absorbant dans un tiroir', 'Dans un verre d\'eau fraîche, jamais chaude (risque de déformation)', 'Dans un verre d\'eau chaude pour le désinfecter', 'Remis immédiatement après le nettoyage, même la nuit'], rep:1, expl:'Le dentier se conserve dans un verre d\'eau froide ou à température ambiante. L\'eau chaude déforme les matériaux. Ne jamais envelopper dans du papier ou une serviette — risque de jeter accidentellement. Des pastilles effervescentes peuvent être ajoutées pour l\'hygiène selon le protocole.' },
  { module:'Module 04 - Soins adaptés', q:'La règle des 5B dans l\'aide à la prise médicamenteuse signifie :', opts:['Bon patient, Bon médicament, Bonne dose, Bonne voie, Bonne heure', 'Bonne hygiène, Bon geste, Bon matériel, Bonne position, Bon résultat', 'Bonne communication, Bon dossier, Bonne traçabilité, Bon soin, Bonne équipe', 'Ces 5B n\'existent pas — c\'est une règle inventée'], rep:0, expl:'La règle des 5B (Bon patient, Bon médicament, Bonne dose, Bonne voie, Bonne heure) est la règle de sécurité de référence pour l\'aide à la prise médicamenteuse. Même si l\'IDE a préparé le pilulier, l\'AS vérifie que le pilulier correspond bien au bon patient avant de le présenter.' },
  { module:'Module 04 - Soins adaptés', q:'Lors de la toilette au lit, à quel moment réajustez-vous la hauteur du lit ?', opts:['Uniquement au début du soin', 'Jamais — le lit reste à hauteur du patient', 'Au début du soin (hauteur de votre bassin) et après, pour remettre le patient confortablement', 'Seulement si vous avez mal au dos'], rep:2, expl:'Le lit se règle à la hauteur de votre propre bassin (crêtes iliaques) pour la réalisation du soin — c\'est un réflexe PRAP fondamental. Après le soin, on remet le lit en position basse pour la sécurité du patient. Cette double manipulation protège à la fois le soignant et le patient.' },
  { module:'Module 06 - Communication', q:'Selon la règle de Mehrabian, quel pourcentage du message passe par le canal non-verbal ?', opts:['7%', '38%', '55%', '80%'], rep:2, expl:'55% du message passe par le non-verbal (posture, regard, expressions, gestes), 38% par le para-verbal (ton, rythme, volume) et seulement 7% par les mots eux-mêmes. C\'est pourquoi l\'AS qui dit \'Je suis là pour vous\' en regardant la porte ne communique pas grand chose.' },
  { module:'Module 06 - Communication', q:'Mme Martin (Alzheimer) dit que sa mère va venir la chercher. Sa mère est décédée depuis 30 ans. Que faites-vous ?', opts:['Vous lui dites clairement que sa mère est décédée pour la ramener à la réalité', 'Vous entrez doucement dans son monde : \'Ah, et elle arrive bientôt ?\' en restant bienveillant', 'Vous changez de sujet immédiatement', 'Vous appelez l\'IDE car c\'est une hallucination'], rep:1, expl:'La méthode Validation de Naomi Feil recommande d\'entrer dans le monde de la personne démente plutôt que de la confronter à une réalité qu\'elle ne peut plus intégrer. Corriger brutalement provoque de l\'angoisse sans bénéfice thérapeutique. Ce n\'est pas mentir — c\'est respecter sa réalité intérieure.' },
  { module:'Module 06 - Communication', q:'Quelle est la différence entre empathie et sympathie dans la relation de soin ?', opts:['Ce sont deux mots pour dire la même chose', 'L\'empathie est la compréhension sans fusion ; la sympathie est la fusion émotionnelle avec la personne', 'La sympathie est plus professionnelle que l\'empathie', 'L\'empathie concerne les soins, la sympathie les familles'], rep:1, expl:'Carl Rogers distingue empathie (comprendre ce que vit la personne de son point de vue, sans se perdre dans son émotion) et sympathie (fusion émotionnelle qui fait perdre la distance professionnelle). La sympathie épuise l\'AS et l\'empêche d\'être objectif. L\'empathie lui permet d\'être pleinement présent tout en restant lui-même.' },
  { module:'Module 06 - Communication', q:'Lors de votre tournée, vous trouvez Mme Dupont avec un hématome sur le bras qu\'elle ne sait pas expliquer. Que faites-vous ?', opts:['Vous notez dans le dossier et signalez à l\'IDE dans la journée', 'Vous signalez immédiatement à l\'IDE avec une description précise de ce que vous avez observé', 'Vous interrogez les autres résidents pour savoir ce qui s\'est passé', 'Vous attendez que l\'hématome soit plus visible pour avoir des certitudes'], rep:1, expl:'Tout signe évocateur de maltraitance se signale immédiatement à l\'IDE — jamais plus tard. L\'AS ne mène pas l\'enquête seul, ne confronte pas l\'auteur présumé, ne juge pas — il décrit précisément ce qu\'il a observé. Le signalement de bonne foi est protégé par la loi.' },
  { module:'Module 06 - Communication', q:'Quelle est la première des 3 conditions de Carl Rogers pour une relation d\'aide efficace ?', opts:['L\'empathie', 'La congruence (authenticité)', 'Le regard positif inconditionnel', 'La bienveillance'], rep:1, expl:'Rogers définit 3 conditions : 1) La congruence (être authentique, en accord avec soi-même), 2) L\'empathie (comprendre le point de vue de l\'autre sans se perdre), 3) Le regard positif inconditionnel (accepter la personne sans jugement). Ces 3 conditions sont nécessaires ET suffisantes pour que la relation aide la personne à évoluer.' },
  { module:'Module 06 - Communication', q:'M. Petit, aphasique après un AVC, ne trouve pas ses mots. Il met du temps à s\'exprimer. Que faites-vous ?', opts:['Vous finissez ses phrases pour lui faire gagner du temps', 'Vous lui donnez le temps nécessaire et attendez patiemment qu\'il s\'exprime', 'Vous posez des questions ouvertes pour l\'aider à s\'exprimer', 'Vous demandez à sa famille de traduire'], rep:1, expl:'En cas d\'aphasie, la règle absolue est de ne jamais finir les phrases à la place de la personne. Donner du temps — même long — est la marque de respect fondamentale. L\'aphasique comprend souvent tout : l\'impatience est perçue et blessante. Des questions fermées (oui/non) et des gestes peuvent aider.' },
  { module:'Module 06 - Communication', q:'Quelle forme de maltraitance est-il le plus difficile à identifier ?', opts:['La maltraitance physique', 'La maltraitance institutionnelle', 'La maltraitance financière', 'La maltraitance sexuelle'], rep:1, expl:'La maltraitance institutionnelle est la moins visible car elle s\'inscrit dans des routines normalisées : lever systématique à 7h sans tenir compte des habitudes, repas pris au lit par défaut, activités imposées... \'On fait toujours comme ça ici\' peut masquer une maltraitance institutionnelle quotidienne.' },
  { module:'Module 06 - Communication', q:'La famille de M. Bernard vous interpelle dans le couloir et vous demande des informations sur son état de santé. Que faites-vous ?', opts:['Vous lui répondez brièvement car c\'est la famille', 'Vous l\'invitez à s\'adresser à l\'IDE ou au médecin pour les informations médicales', 'Vous lui dites que vous ne savez pas', 'Vous lui communiquez les informations de base car c\'est son droit'], rep:1, expl:'Le secret professionnel s\'applique aussi aux familles. L\'AS ne divulgue pas d\'informations médicales — même à la famille directe. Il oriente vers l\'IDE ou le médecin. Seul le patient peut autoriser la communication d\'informations médicales à sa famille (Loi 2002-303 relative aux droits des malades).' },
  { module:'Module 06 - Communication', q:'La proxémique de Edward Hall définit 4 zones de distance. Dans quelle zone entre l\'AS lors de la toilette ?', opts:['Zone publique', 'Zone sociale', 'Zone personnelle', 'Zone intime'], rep:3, expl:'La zone intime (0 à 45 cm) est la zone du soin, de la toilette, du contact physique. Elle est normalement réservée aux très proches. L\'AS y entre à chaque soin — ce qui impose un protocole strict : frapper, se présenter, expliquer le geste avant de toucher. Entrer dans la zone intime sans prévenir est vécu comme une agression.' },
  { module:'Module 06 - Communication', q:'Qu\'est-ce que le \'regard positif inconditionnel\' selon Rogers ?', opts:['Sourire en permanence à la personne', 'Accepter la personne telle qu\'elle est, sans jugement, quels que soient ses actes passés ou son comportement', 'Approuver tous les choix de la personne même dangereux', 'Trouver quelque chose de positif à dire à chaque interaction'], rep:1, expl:'Le regard positif inconditionnel de Rogers signifie accueillir la personne telle qu\'elle est — sa valeur intrinsèque n\'est pas conditionnée à son comportement ou à son histoire. Un résident agressif, alcoolique, ou au passé difficile mérite d\'être soigné avec la même dignité. Ce n\'est pas approuver ses actes — c\'est respecter sa personne.' },
  { module:'Module 07 - Formation professionnelle', q:'La formation DEAS comprend au total :', opts:['770 heures de théorie uniquement', '1 540 heures au total — 770h de théorie et 770h de stages', '1 000 heures de cours et 540 heures de stages', '2 ans de formation à plein temps'], rep:1, expl:'Le DEAS se prépare en 1 540 heures réparties équitablement : 770h de formation théorique (10 modules sur 22 semaines) et 770h de stages pratiques (4 stages sur 22 semaines). C\'est une formation en alternance qui intègre théorie et pratique de façon complémentaire.' },
  { module:'Module 07 - Formation professionnelle', q:'La certification DEAS est organisée en :', opts:['Un examen final unique en fin d\'année', '5 blocs de compétences capitalisables — on peut obtenir les blocs séparément', '10 épreuves correspondant aux 10 modules', 'Un mémoire de fin de formation'], rep:1, expl:'Le DEAS est organisé en 5 blocs de compétences capitalisables. Si un bloc n\'est pas validé, l\'étudiant peut le repasser sans recommencer toute la formation. Cette organisation par blocs permet une certification progressive et flexible.' },
  { module:'Module 07 - Formation professionnelle', q:'Lors de votre entretien d\'accueil en stage, le tuteur vous demande vos objectifs. Quelle est la meilleure réponse ?', opts:['\'Je veux tout apprendre\' — montrer de la motivation générale', '\'Je n\'ai pas d\'objectifs précis, je m\'adapte à ce qu\'on me propose\'', '\'Je souhaite progresser sur la communication avec les personnes atteintes de démence et améliorer ma technique de toilette au lit\'', '\'Mon objectif est d\'obtenir une bonne note pour valider mon stage\''], rep:2, expl:'Les bons objectifs de stage sont concrets, personnels et liés aux compétences DEAS. Un objectif générique (\'tout apprendre\') ou une absence d\'objectif montre un manque de préparation. Un objectif orienté vers la note montre une mauvaise compréhension du tutorat — l\'objectif est la progression, pas la performance.' },
  { module:'Module 07 - Formation professionnelle', q:'Vous commettez une erreur lors d\'un soin en stage. Que faites-vous ?', opts:['Vous ne dites rien — ça s\'est bien terminé', 'Vous signalez l\'erreur au tuteur immédiatement et transparence totale', 'Vous attendez de voir si ça a des conséquences avant de signaler', 'Vous en parlez à un collègue mais pas au tuteur'], rep:1, expl:'Une erreur signalée immédiatement et honnêtement est valorisée par les tuteurs et les formateurs. Elle montre la maturité professionnelle et le sens des responsabilités. Une erreur cachée qui se découvre plus tard est beaucoup plus grave. La transparence protège le patient et le stagiaire.' },
  { module:'Module 07 - Formation professionnelle', q:'Le portfolio de formation DEAS est :', opts:['Un classeur de photocopies de cours', 'Un document personnel retraçant votre parcours, vos apprentissages et votre progression, présenté lors de la certification', 'Un carnet de notes imposé par l\'IFAS', 'Le relevé de vos notes obtenues en cours'], rep:1, expl:'Le portfolio est un document vivant et personnel — pas un classeur de cours. Il contient votre présentation, les fiches de suivi par compétence, les bilans de stage, les situations significatives analysées et votre auto-évaluation. Il est présenté lors des entretiens de certification.' },
  { module:'Module 07 - Formation professionnelle', q:'Une situation significative dans le portfolio, c\'est :', opts:['Un résumé de votre meilleure journée de stage', 'Une analyse réflexive d\'un moment qui vous a appris quelque chose — incluant vos sentiments, vos actions et ce que vous en retirez', 'La liste de tous les soins réalisés pendant le stage', 'Un texte copié d\'un manuel sur la compétence travaillée'], rep:1, expl:'Une situation significative est une analyse réflexive, pas un compte-rendu factuel. Elle décrit la situation, vos sentiments du moment, vos actions, votre apprentissage et ce que vous feriez différemment. Les formateurs cherchent votre capacité à réfléchir sur votre pratique — une \'mauvaise\' situation bien analysée vaut mieux qu\'une \'bonne\' mal décrite.' },
  { module:'Module 07 - Formation professionnelle', q:'Le DPC (Développement Professionnel Continu) est pour les AS :', opts:['Facultatif — seulement pour ceux qui veulent évoluer', 'Une obligation légale — minimum une action tous les 3 ans', 'Obligatoire seulement pour les AS en hôpital', 'Réservé aux AS ayant plus de 5 ans d\'ancienneté'], rep:1, expl:'Le DPC est une obligation légale pour tous les professionnels de santé, y compris les AS. Minimum une action de DPC tous les 3 ans, financée par l\'employeur ou via le CPF. Les attestations de formation doivent être conservées car elles peuvent être demandées lors de contrôles.' },
  { module:'Module 07 - Formation professionnelle', q:'L\'arrêté du 26 février 2025 crée une formation d\'actualisation pour :', opts:['Tous les AS sans exception', 'Les AS diplômés avant 2021 uniquement — les AS diplômés après 2021 ont déjà ces compétences dans leur référentiel', 'Les AS travaillant en EHPAD uniquement', 'Les AS souhaitant évoluer vers le grade d\'IDE'], rep:1, expl:'La formation d\'actualisation de l\'arrêté 2025 (3 modules : paramètres vitaux, soins aigus, situations à risque) est destinée aux AS diplômés AVANT 2021. Ces compétences sont déjà intégrées dans le référentiel DEAS rénové de 2021 — les AS formés après cette date n\'ont pas besoin de cette actualisation.' },
  { module:'Module 07 - Formation professionnelle', q:'Lors d\'un entretien d\'embauche, on vous demande \'Quels sont vos défauts ?\' La meilleure réponse est :', opts:['\'Je n\'ai pas de défauts.\'', '\'Je suis perfectionniste, ce qui me prenait plus de temps qu\'il ne le faudrait — j\'apprends à mieux prioriser.\'', '\'Je suis parfois trop passionné par mon travail.\'', 'Ne rien dire et sourire poliment'], rep:1, expl:'La question sur les défauts teste votre honnêteté et votre conscience professionnelle. La bonne stratégie : un défaut réel mais en cours de travail, montrant que vous vous connaissez et que vous progressez. \'Je n\'ai pas de défauts\' est éliminatoire. \'Je suis trop passionné\' est un cliché transparent.' },
  { module:'Module 07 - Formation professionnelle', q:'Le 4e stage du DEAS est :', opts:['Obligatoirement en EHPAD', 'Obligatoirement en service de médecine', 'Au libre choix de l\'étudiant selon son projet professionnel', 'Obligatoirement en psychiatrie'], rep:2, expl:'Les 3 premiers stages sont imposés (EHPAD, médecine/chirurgie, psychiatrie/handicap). Le 4e stage est au libre choix de l\'étudiant selon son projet professionnel — c\'est l\'occasion de découvrir un secteur qui vous attire particulièrement ou d\'approfondir un domaine déjà rencontré.' },
  { module:'Module 08 - Hygiène et entretien', q:'Vous devez désinfecter la table de nuit de M. Dupont. Dans quel ordre procédez-vous ?', opts:['Désinfecter directement — c\'est plus rapide', 'Nettoyer avec détergent → rincer → désinfecter → sécher', 'Désinfecter → nettoyer → sécher', 'Nettoyer → désinfecter sans rincer entre les deux'], rep:1, expl:'L\'ordre est obligatoire : nettoyer (détergent), rincer (le détergent inactiverait le désinfectant), désinfecter (respecter le temps de contact), sécher (l\'humidité favorise la repousse bactérienne). Désinfecter sans nettoyer = inefficace car les salissures protègent les microbes.' },
  { module:'Module 08 - Hygiène et entretien', q:'Vous venez de changer la protection souillée de Mme Aubert. Selon les 5 moments OMS, quelle est votre prochaine action ?', opts:['Passer au résident suivant directement', 'Friction SHA après avoir retiré les gants', 'Mettre de nouveaux gants pour le prochain soin', 'Remplir le dossier de soins'], rep:1, expl:'Les 5 moments OMS : après tout contact avec le patient et son environnement → SHA obligatoire. La séquence correcte est : retirer les gants EN PREMIER (les plus contaminés), puis friction SHA avant de passer au patient suivant ou de toucher quoi que ce soit.' },
  { module:'Module 08 - Hygiène et entretien', q:'Dans quel cas le lavage au savon est-il OBLIGATOIRE plutôt que la SHA ?', opts:['Toujours — le savon est plus efficace', 'Jamais — la SHA suffit toujours', 'En cas de Clostridium difficile, de Norovirus, ou si les mains sont visiblement souillées', 'Seulement si on a le temps'], rep:2, expl:'La SHA est inefficace sur les spores de C. difficile et le Norovirus. Dans ces cas, et si les mains sont visiblement souillées ou en sortant des toilettes, le lavage au savon est obligatoire. Pour tout le reste, la SHA est préférentielle car plus efficace et moins agressante pour la peau.' },
  { module:'Module 08 - Hygiène et entretien', q:'Après un soin, vous trouvez une aiguille traînant sur le chariot. Que faites-vous ?', opts:['La ramasser à la main et la jeter dans la poubelle noire', 'La recapuchonner puis la mettre dans le conteneur rigide', 'La saisir avec une pince ou une compresse et la déposer directement dans le conteneur rigide jaune', 'La laisser — ce n\'est pas votre rôle'], rep:2, expl:'Les aiguilles vont TOUJOURS dans le conteneur rigide jaune — jamais dans un sac souple. On ne recapuchonne jamais à la main (risque de piqûre). On saisit l\'aiguille avec une protection (pince, compresse) et on la dépose directement dans le conteneur sans la recapuchonner.' },
  { module:'Module 08 - Hygiène et entretien', q:'Vous vous piquez accidentellement avec une aiguille souillée. Votre première action est :', opts:['Faire saigner la plaie abondamment', 'Ne pas faire saigner — laver à l\'eau et au savon 5 minutes, désinfecter, et signaler immédiatement', 'Mettre un pansement et finir votre service avant de signaler', 'Attendre de voir si une infection se développe'], rep:1, expl:'Contrairement aux idées reçues, faire saigner n\'élimine pas les virus. La procédure AES : ne pas faire saigner, laver eau + savon 5 min, désinfecter (Dakin ou alcool 70°), signaler immédiatement au cadre, se rendre aux urgences ou médecin du travail dans les 4 heures (traitement préventif VIH si nécessaire).' },
  { module:'Module 08 - Hygiène et entretien', q:'M. Bernard est en isolement contact pour SARM. Vous entrez dans sa chambre pour lui apporter son repas. Que devez-vous porter ?', opts:['Rien — c\'est juste pour apporter le repas', 'Juste des gants — le masque n\'est pas nécessaire', 'Gants ET surblouse obligatoirement — même pour une courte durée', 'Gants, surblouse et masque FFP2'], rep:2, expl:'L\'isolement contact exige gants + surblouse pour TOUTE entrée dans la chambre, quelle que soit la durée ou le motif. Le SARM se transmet par contact — même apporter un plateau peut suffire à contaminer les mains et la tenue si non protégé.' },
  { module:'Module 08 - Hygiène et entretien', q:'Quelle est la différence entre un détergent et un désinfectant ?', opts:['Ce sont deux mots pour la même chose', 'Le détergent nettoie mais ne tue pas les microbes. Le désinfectant tue les microbes mais ne nettoie pas', 'Le détergent est plus puissant que le désinfectant', 'Le désinfectant peut s\'utiliser sans détergent si on appuie fort'], rep:1, expl:'Le détergent nettoie (élimine les salissures) mais ne désinfecte pas. Le désinfectant tue les microbes mais ne nettoie pas. C\'est pourquoi les deux étapes sont nécessaires dans cet ordre : nettoyer d\'abord pour que le désinfectant puisse agir sur une surface propre.' },
  { module:'Module 08 - Hygiène et entretien', q:'Dans quel ordre doit-on retirer ses EPI après un soin en isolement contact ?', opts:['Masque en premier car il gêne la respiration', 'Gants en premier — ce sont les plus contaminés — puis SHA, surblouse, masque, SHA', 'Surblouse, gants, masque, SHA', 'N\'importe quel ordre si on fait une SHA à la fin'], rep:1, expl:'L\'ordre de déshabillage va du plus contaminé au moins contaminé : gants (plus contaminés) → SHA → lunettes → surblouse/tablier → masque (tenir par les élastiques, ne jamais toucher la face avant) → SHA. Cet ordre évite de contaminer le visage et les zones propres avec les gants ou la surblouse souillés.' },
  { module:'Module 08 - Hygiène et entretien', q:'Le conteneur rigide pour perforants doit être fermé quand :', opts:['Il est complètement plein', 'Il est rempli aux 3/4 maximum', 'À la fin de chaque service, quelle que soit son état de remplissage', 'Quand l\'IDE le demande'], rep:1, expl:'Le conteneur rigide se ferme aux 3/4 plein — jamais complètement plein. Un conteneur trop rempli devient impossible à fermer correctement et dangereux à manipuler. Il ne faut jamais forcer ou comprimer le contenu pour en mettre plus.' },
  { module:'Module 08 - Hygiène et entretien', q:'Mme L. est hospitalisée pour tuberculose pulmonaire. Quel masque devez-vous porter pour entrer dans sa chambre ?', opts:['Aucun masque — la tuberculose ne se transmet pas par l\'air', 'Masque chirurgical classique', 'Masque FFP2 obligatoirement', 'Masque FFP2 seulement si elle tousse'], rep:2, expl:'La tuberculose pulmonaire est une infection aéroportée — elle se transmet via de très fines particules en suspension dans l\'air (aérosols). Le masque chirurgical ne filtre pas les aérosols. Le masque FFP2 est obligatoire pour toute personne entrant dans la chambre, que la patiente tousse ou non.' },
  { module:'Module 09 - Traitement des informations', q:'La transmission \'RAS — Mme Dupont va bien\' est-elle acceptable dans le dossier de soins ?', opts:['Oui — simple et rapide', 'Oui si rien de particulier ne s\'est passé', 'Non — trop vague, non factuelle, sans valeur juridique', 'Non seulement si la personne est malade'], rep:2, expl:'\'RAS\' et \'va bien\' sont des formulations interdites dans un dossier de soins. Elles ne prouvent pas que les soins ont été réalisés, ne donnent aucune information utile à l\'équipe suivante et n\'ont pas de valeur juridique. La transmission correcte décrit factuellement ce qui a été observé et réalisé.' },
  { module:'Module 09 - Traitement des informations', q:'Dans la méthode DAR, la lettre \'A\' correspond à :', opts:['Anomalie — ce qui ne va pas', 'Action — ce que j\'ai fait suite à l\'observation', 'Alerte — qui j\'ai prévenu', 'Analyse — mon interprétation'], rep:1, expl:'DAR = Donnée (ce que j\'ai observé), Action (ce que j\'ai fait), Résultat (l\'effet de mon action). La lettre A correspond à l\'action réalisée par le soignant — signaler à l\'IDE, proposer une alternative, adapter le soin.' },
  { module:'Module 09 - Traitement des informations', q:'La fille d\'un résident vous demande comment va son père. Quelle est la bonne réponse ?', opts:['Vous lui donnez toutes les informations médicales — c\'est sa famille', 'Vous lui dites que son père va bien pour la rassurer', 'Vous l\'invitez à s\'adresser à l\'infirmière ou à son père directement', 'Vous lui montrez le dossier de soins'], rep:2, expl:'La famille n\'a pas automatiquement accès aux informations médicales — uniquement si le patient a donné son accord explicite. L\'AS oriente vers l\'IDE ou le cadre, sans donner d\'information ni mentir. Montrer le dossier est une violation du secret professionnel.' },
  { module:'Module 09 - Traitement des informations', q:'Vous faites une erreur dans une transmission écrite papier. Que faites-vous ?', opts:['Vous utilisez du blanc correcteur pour effacer', 'Vous rayez complètement et recommencez', 'Vous tracez un seul trait sur l\'erreur, écrivez \'erreur\', datez et paraphez', 'Vous déchirez la feuille et en prenez une nouvelle'], rep:2, expl:'L\'utilisation de blanc correcteur ou la suppression d\'une donnée médicale est une falsification de document médical — faute grave. La procédure correcte : un seul trait sur l\'erreur (le texte doit rester lisible), le mot \'erreur\', la date et les initiales. En numérique, une note corrective est ajoutée sans supprimer la saisie initiale.' },
  { module:'Module 09 - Traitement des informations', q:'Le secret professionnel pour l\'AS s\'applique :', opts:['Uniquement pendant les heures de service', 'Uniquement dans l\'établissement', 'Toujours — y compris après la fin du contrat et même après le décès du patient', 'Seulement pour les informations médicales graves'], rep:2, expl:'Le secret professionnel est permanent et absolu. Il s\'applique dans tous les lieux (y compris hors de l\'établissement), à tout moment (y compris après la fin du contrat), et pour toutes les informations (y compris après le décès du patient). La violation est punie d\'un an de prison et 15 000 € d\'amende.' },
  { module:'Module 09 - Traitement des informations', q:'Dans la méthode SBAR, la lettre \'S\' correspond à :', opts:['Soins — les actes réalisés', 'Situation — qui est le patient et quel est le problème', 'Signalement — qui j\'ai prévenu', 'Surveillance — ce que j\'ai observé'], rep:1, expl:'SBAR = Situation (qui et le problème), Background (contexte), Assessment (observation), Recommandation (ce que je suggère). Le S permet d\'identifier immédiatement de qui on parle et pourquoi on transmet — indispensable en début de toute communication orale urgente.' },
  { module:'Module 09 - Traitement des informations', q:'Vous observez qu\'une résidente pleure pendant la toilette sans explication. Comment le notez-vous dans le dossier ?', opts:['\'Elle est triste\' — simple et clair', '\'Elle pleure pendant la toilette du 12/03 à 8h15 — dit que sa fille ne vient plus la voir. Signalé à l\'IDE.\'', '\'RAS sauf humeur\' — pour noter qu\'il y a quelque chose', '\'Comportement émotionnel anormal lors du soin\''], rep:1, expl:'La bonne transmission est factuelle (pleure), datée (12/03 à 8h15), contextuelle (pendant la toilette), cite les mots de la personne entre guillemets et mentionne la transmission à l\'IDE. \'Elle est triste\' est une interprétation — pas une observation. \'Comportement émotionnel anormal\' est du jargon sans valeur pratique.' },
  { module:'Module 09 - Traitement des informations', q:'Qui peut accéder au dossier de soins d\'un patient ?', opts:['Tout le personnel de l\'établissement', 'Uniquement le médecin et l\'IDE', 'Les professionnels de santé qui prennent en charge ce patient, et le patient lui-même sur demande', 'La famille directe sans restriction'], rep:2, expl:'L\'accès au dossier patient est strictement limité aux professionnels qui prennent en charge ce patient spécifique (pas tous les soignants de l\'établissement) et au patient lui-même qui peut en faire la demande à tout moment. La famille n\'y a pas accès sans accord du patient.' },
  { module:'Module 09 - Traitement des informations', q:'Vous n\'avez pas eu le temps de tracer les soins du matin pendant votre service très chargé. En fin de service, vous tracez tout de mémoire. Cette pratique est :', opts:['Acceptable — l\'essentiel est que ce soit tracé', 'Recommandée pour ne pas perturber les soins', 'Risquée — les souvenirs peuvent être inexacts et la valeur juridique est réduite. Mieux vaut noter rapidement sur papier pendant le service', 'Interdite — si ce n\'est pas tracé en temps réel, c\'est inexistant'], rep:2, expl:'Tracer de mémoire plusieurs heures après expose à des erreurs (confusion entre résidents, oubli de valeurs précises) et à une valeur juridique réduite. La bonne pratique est de noter sur un support papier pendant le service (heure + observation) et de saisir dans le DPI dès que possible avec l\'heure réelle de l\'acte.' },
  { module:'Module 09 - Traitement des informations', q:'Discuter de l\'état d\'un résident avec votre collègue dans l\'ascenseur est :', opts:['Acceptable si vous parlez à voix basse', 'Acceptable entre soignants de la même équipe', 'Une violation du secret professionnel — lieu public', 'Acceptable si vous ne citez pas le nom du résident'], rep:2, expl:'L\'ascenseur est un lieu public où d\'autres personnes peuvent entendre. Parler d\'un patient dans un lieu public est une violation du secret professionnel — même sans citer le nom (la description peut suffire à identifier la personne). Les transmissions se font en salle de soins, bureau fermé, ou par écrit dans le dossier.' },
  { module:'Module 10 - Travail en équipe', q:'L\'IDE est en pause et vous lui avez signalé que M. Dupont a une glycémie à 0,48 g/L. Elle vous dit : \'Donnez-lui du jus d\'orange, je viens dès que je peux.\' Cette délégation verbale est-elle suffisante ?', opts:['Oui — l\'IDE a donné un ordre oral, c\'est suffisant', 'Non — une délégation doit être écrite pour être valable. Demander à l\'IDE de venir évaluer directement', 'Oui si vous notez l\'heure dans le dossier', 'Non — l\'AS ne peut jamais donner quoi que ce soit sans prescription écrite du médecin'], rep:1, expl:'Une délégation verbale dans l\'urgence peut être acceptée mais doit être formalisée par écrit le plus tôt possible. Pour une hypoglycémie à 0,48 g/L, l\'IDE doit évaluer directement — le risque de perte de conscience est réel et l\'AS ne peut pas assumer seul cette décision thérapeutique. La bonne conduite est d\'insister pour que l\'IDE vienne évaluer.' },
  { module:'Module 10 - Travail en équipe', q:'Votre collègue IDE vous demande de poser la perfusion de Mme Martin car elle est débordée. Que faites-vous ?', opts:['Vous posez la perfusion — c\'est une urgence pour elle', 'Vous expliquez que la pose de perfusion est hors de vos compétences et proposez de l\'aider autrement', 'Vous posez la perfusion si votre tuteur de stage vous a montré comment faire', 'Vous demandez au cadre si vous pouvez le faire exceptionnellement'], rep:1, expl:'La pose de perfusion est un acte IDE exclusif — il ne peut pas être délégué à l\'AS, même dans l\'urgence, même avec formation pratique informelle. L\'AS explique calmement et propose une aide dans son champ de compétences (préparer le matériel, surveiller la personne, prévenir le cadre si l\'IDE est vraiment débordée).' },
  { module:'Module 10 - Travail en équipe', q:'Pendant la RCP, à quel rythme doit-on réaliser les compressions thoraciques ?', opts:['60 compressions par minute — assez lent pour être efficace', '80 à 100 compressions par minute', '100 à 120 compressions par minute', 'Le plus vite possible — plus c\'est rapide, mieux c\'est'], rep:2, expl:'Le rythme recommandé par les guidelines de réanimation est de 100 à 120 compressions par minute. En dessous de 100, le débit cardiaque est insuffisant. Au-dessus de 120, les compressions ne sont plus assez profondes. En pratique : compter à voix haute \'un-et-deux-et-trois...\' aide à maintenir le rythme.' },
  { module:'Module 10 - Travail en équipe', q:'Un événement indésirable (EI) doit être signalé :', opts:['Uniquement si le patient a été blessé', 'Uniquement pour les erreurs médicamenteuses graves', 'Pour tout incident ayant causé ou pu causer un dommage — même sans conséquence visible', 'Seulement si le cadre le demande'], rep:2, expl:'Le signalement des EI concerne tous les incidents — y compris les \'presque-accidents\' (presqu\'erreur qui ne s\'est pas produite). L\'objectif est d\'améliorer la sécurité collective, pas de sanctionner. Un établissement avec peu d\'EI signalés n\'est pas plus sûr — il signale peut-être moins. Le signalement est protégé par la loi.' },
  { module:'Module 10 - Travail en équipe', q:'L\'AFGSU niveau 1 doit être renouvelée :', opts:['Tous les ans', 'Tous les 2 ans', 'Tous les 4 ans', 'Elle est valable à vie une fois obtenue'], rep:2, expl:'L\'AFGSU niveau 1 doit être renouvelée tous les 4 ans par une formation de recyclage de 6 heures. Les techniques de réanimation évoluent et le recyclage permet de maintenir les compétences à jour. L\'attestation périmée peut bloquer l\'exercice professionnel.' },
  { module:'Module 10 - Travail en équipe', q:'Vous trouvez M. Bernard inconscient et vous réalisez qu\'il ne respire pas. Quelle est votre première action après avoir vérifié la sécurité ?', opts:['Commencer immédiatement les compressions thoraciques', 'Appeler à l\'aide et alerter le 15 (ou faire appeler)', 'Chercher le chariot d\'urgence dans le couloir', 'Prendre son pouls pendant 1 minute pour confirmer l\'arrêt cardiaque'], rep:1, expl:'La chaîne de survie commence par l\'alerte — appeler à l\'aide et le 15 (ou faire appeler par quelqu\'un d\'autre si vous n\'êtes pas seul). Ensuite seulement démarrer la RCP. Partir chercher du matériel en laissant la personne seule est une erreur. Chercher le pouls pendant 1 minute fait perdre un temps précieux.' },
  { module:'Module 10 - Travail en équipe', q:'Un résident fait une fausse route et tousse encore vigoureusement. Que faites-vous ?', opts:['Donner des claques dans le dos immédiatement', 'L\'encourager à continuer de tousser — la toux efficace est le meilleur mécanisme', 'Lui donner à boire pour faire passer le morceau', 'Pratiquer immédiatement la manœuvre de Heimlich'], rep:1, expl:'Tant que la personne tousse efficacement (toux forte, peut parler, est consciente), il ne faut pas intervenir — la toux est le mécanisme naturel le plus efficace pour libérer les voies aériennes. Les claques et Heimlich sont réservés à l\'obstruction totale (personne qui ne peut plus parler, ni tousser, ni respirer).' },
  { module:'Module 10 - Travail en équipe', q:'Quelle grille évalue le risque de chute chez un résident ?', opts:['Grille de Braden', 'Grille de Morse', 'Grille AGGIR', 'Grille DOLOPLUS'], rep:1, expl:'La grille de Morse évalue le risque de chute (antécédents de chute, diagnostic secondaire, aide à la marche, perfusion IV, démarche, état mental). La grille de Braden évalue le risque d\'escarre. La grille AGGIR évalue le niveau de dépendance (GIR). DOLOPLUS évalue la douleur chez les personnes démentes.' },
  { module:'Module 10 - Travail en équipe', q:'Un conflit entre vous et un collègue AS s\'installe depuis 2 semaines. La meilleure démarche est :', opts:['Ignorer — ça finira par passer', 'En parler à tous les collègues pour avoir leur soutien', 'Aborder directement la situation avec la personne concernée, au bon moment et en utilisant le \'je\'', 'Attendre que le cadre s\'en aperçoive et intervienne'], rep:2, expl:'La démarche directe et bienveillante est recommandée : choisir le bon moment (pas en plein soin, pas devant les résidents), utiliser le \'je\' (\'je me suis senti exclu\' plutôt que \'tu ne m\'écoutes jamais\'), écouter la réponse. Si le conflit persiste après cette tentative, escalader vers le cadre. Parler aux collègues avant d\'aborder directement = triangulation qui amplifie le conflit.' },
  { module:'Module 10 - Travail en équipe', q:'L\'arrêté du 26 février 2025 a élargi les compétences AS. Parmi ces actes, lequel reste HORS du champ AS même après cet arrêté ?', opts:['Mesure de la glycémie capillaire', 'Surveillance d\'une perfusion en cours', 'Pose d\'un suppositoire', 'Pose d\'une sonde urinaire'], rep:3, expl:'La pose de sonde urinaire reste un acte IDE exclusif — elle n\'est pas dans le champ de l\'arrêté 2025. En revanche, l\'arrêté 2025 a intégré dans le champ AS : glycémie capillaire, SpO2, administration d\'O2 (débit prescrit), suppositoires, soins de stomie courants, surveillance d\'une perfusion en cours.' },
  { module:'Module B - Soins aigus', q:'Mme Aubert (diabétique) est confuse et tremble. Sa glycémie est à 0,55 g/L. Quelle est votre première action ?', opts:['Lui donner immédiatement un jus de fruit', 'Appeler l\'IDE avec la valeur et les signes cliniques avant de donner quoi que ce soit', 'Attendre que l\'IDE passe dans sa prochaine tournée', 'Augmenter son repas du midi'], rep:1, expl:'En cas de conscience altérée, on n\'administre rien par voie orale sans accord IDE (risque de fausse route). La première action est d\'alerter l\'IDE avec méthode SBAR : valeur, signes, contexte (repas incomplet ce matin).' },
  { module:'Module B - Soins aigus', q:'Vous changez les lunettes à oxygène de M. Bernard (BPCO). La prescription indique 2 L/min. Sa SpO2 reste à 88 % après le changement. Que faites-vous ?', opts:['Augmenter à 3 L/min pour améliorer sa SpO2', 'Retirer les lunettes et mettre un masque', 'Informer l\'IDE en lui transmettant la SpO2 et l\'heure — ne pas modifier le débit seul', 'Attendre 30 minutes avant d\'appeler'], rep:2, expl:'En BPCO, modifier le débit d\'O2 sans ordre médical est dangereux (risque de dépression respiratoire). L\'AS ne modifie jamais le débit seul. Il transmet la SpO2 à l\'IDE qui adaptera la prescription si nécessaire.' },
  { module:'Module B - Soins aigus', q:'Lors du changement de la poche de colostomie de Mme Rose, vous observez que la stomie est violacée et qu\'il y a un léger saignement. Que faites-vous ?', opts:['Vous posez quand même la nouvelle poche en notant l\'observation dans le dossier', 'Vous stoppez le soin, recouvrez d\'une compresse humide et alertez l\'IDE immédiatement', 'Vous nettoyez plus vigoureusement pour faire disparaître le saignement', 'Vous attendez la prochaine toilette pour voir si ça s\'améliore'], rep:1, expl:'Une stomie violacée ou saignante sort du champ d\'action AS lors du changement de routine. Il faut stopper, protéger (compresse humide) et alerter l\'IDE immédiatement. Poser une nouvelle poche sans évaluation médicale risque de masquer une complication grave.' },
  { module:'Module B - Soins aigus', q:'L\'évaluation qualité du soin selon l\'arrêté 2025 implique que l\'AS :', opts:['Réalise le soin et passe au suivant sans s\'attarder', 'Observe le résultat du soin, évalue si l\'objectif est atteint et signale tout écart à l\'IDE', 'Laisse l\'IDE évaluer le résultat lors de sa prochaine tournée', 'Note simplement que le soin a été réalisé dans le dossier'], rep:1, expl:'L\'arrêté 2025 introduit explicitement la notion d\'évaluation et de réajustement par l\'AS. Après chaque soin délégué, l\'AS évalue : l\'objectif est-il atteint ? Y a-t-il des effets indésirables ? Faut-il réajuster ? Ce résultat est tracé et transmis à l\'IDE.' },
  { module:'Module B - Soins aigus', q:'Une aide-soignante collègue vous demande de \'distribuer les médicaments rapidement\' parce qu\'elle est débordée. Que faites-vous ?', opts:['Vous le faites — c\'est pour aider l\'équipe', 'Vous refusez clairement et expliquez que ce n\'est pas dans vos compétences, et proposez d\'aider autrement', 'Vous le faites mais sans le noter dans le dossier', 'Vous demandez l\'accord verbal d\'un médecin par téléphone'], rep:1, expl:'La distribution de médicaments est un acte IDE. Le faire expose l\'AS à des sanctions disciplinaires et pénales, quelle que soit la raison invoquée. La bonne réponse est de refuser clairement et de proposer une autre aide (prendre en charge d\'autres soins pour libérer l\'IDE).' },
  { module:'Module B - Soins aigus', q:'Lors de la pose d\'un suppositoire, la bonne position du patient est :', opts:['Position assise sur les toilettes', 'Décubitus dorsal (sur le dos)', 'Décubitus latéral gauche (couché sur le côté gauche)', 'Position semi-assise à 45°'], rep:2, expl:'Le décubitus latéral gauche facilite l\'introduction du suppositoire dans la partie gauche du côlon (côlon descendant et sigmoïde), où il sera le plus efficace. C\'est la position de référence pour cet acte.' },
  { module:'Module B - Soins aigus', q:'Que signifie \'réajuster\' un soin selon l\'arrêté 2025 ?', opts:['Refaire exactement le même soin si ça n\'a pas fonctionné', 'Adapter sa conduite en fonction du résultat observé — parfois s\'arrêter et appeler l\'IDE', 'Déléguer le soin à un collègue plus expérimenté', 'Noter dans le dossier que le soin sera à refaire'], rep:1, expl:'Réajuster, c\'est adapter. Si l\'objectif est atteint : tracer et continuer. Si l\'objectif n\'est pas atteint : ne pas réitérer aveuglément mais informer l\'IDE qui adaptera la prescription. Si complication : stop and call. Le réajustement peut aller de l\'adaptation mineure à l\'arrêt du soin.' },
  { module:'Module B - Soins aigus', q:'Vous surveillez la perfusion de M. Garnier. Vous observez que la zone de ponction est gonflée et douloureuse. Que faites-vous ?', opts:['Vous accélérez le débit pour que la perfusion finisse plus vite', 'Vous ralentissez le débit et attendez que ça passe', 'Vous arrêtez le débit en clampant le tuyau et alertez l\'IDE immédiatement', 'Vous changez la poche de perfusion'], rep:2, expl:'Un gonflement et une douleur au site de ponction signent une extravasation (la perfusion ne coule plus dans la veine mais dans les tissus). L\'AS clamp le tuyau (sans déconnecter) et alerte l\'IDE immédiatement. Ne pas continuer à perfuser dans un tissu.' },
  { module:'Module B - Soins aigus', q:'M. René reçoit de l\'oxygène par masque. Avant de lui mettre un masque neuf, vous devez vérifier :', opts:['Que le masque est de la bonne couleur', 'La taille adaptée au visage, le débit prescrit sur le détendeur, l\'absence de rougeurs sur le visage', 'Que M. René n\'a pas mangé depuis 2 heures', 'Que la pièce est bien ventilée'], rep:1, expl:'Avant la pose d\'un masque : vérifier la taille (petit/moyen/grand), confirmer le débit prescrit sur le détendeur (ne pas le modifier), et inspecter la peau du visage pour prévenir les lésions de pression. L\'AS positionne le masque, pince l\'attache nasale et vérifie l\'étanchéité.' },
  { module:'Module B - Soins aigus', q:'La traçabilité dans le dossier patient après un soin délégué doit obligatoirement comporter :', opts:['Juste \'soin fait\' avec votre initiale', 'La date, l\'heure précise, la valeur mesurée, le résultat clinique observé et la transmission effectuée', 'Uniquement les soins qui se sont mal passés', 'Le nom du médecin qui a prescrit'], rep:1, expl:'L\'arrêté 2025 exige la traçabilité avec exactitude. Une entrée dans le dossier doit comporter : date + heure précise, valeur exacte (jamais \'normal\'), résultat clinique (la personne a été soulagée, la SpO2 a remonté à X %), et toute transmission effectuée à l\'IDE avec l\'heure.' },
  { module:'Module C - Repérer et alerter', q:'L\'objectif 1 du Module C demande à l\'AS d\'identifier les fragilités et de :', opts:['Les traiter lui-même dans la limite de ses compétences', 'Transmettre les informations nécessaires dans le cadre d\'une collaboration pluriprofessionnelle', 'Les noter dans le dossier sans en parler à l\'équipe', 'Attendre que la personne se plaigne avant d\'agir'], rep:1, expl:'L\'objectif 1 du Module C est précis : identifier ET transmettre dans le cadre pluriprofessionnel. L\'AS ne reste jamais seul face à une fragilité. Il est le premier observateur, mais c\'est l\'équipe pluripro qui prend les décisions thérapeutiques.' },
  { module:'Module C - Repérer et alerter', q:'Une personne âgée pleure lors de la toilette depuis plusieurs jours et refuse de sortir de sa chambre. L\'AS suspecte une dépression. Quelle est sa conduite à tenir ?', opts:['Diagnostiquer une dépression dans le dossier et informer la famille', 'Observer, noter les faits objectivement et transmettre à l\'IDE en utilisant la méthode SBAR', 'Prescrire lui-même une activité pour sortir la personne de sa chambre', 'Attendre que ça passe — c\'est normal chez la personne âgée'], rep:1, expl:'L\'AS n\'établit pas de diagnostic (c\'est le rôle médical) mais il observe, note factuellement et transmet. La méthode SBAR lui permet de structurer sa transmission : Situation (pleure depuis 3 jours, refus de sortir), Background (âge, antécédents), Assessment (observation), Recommandation (évaluation psy souhaitée).' },
  { module:'Module C - Repérer et alerter', q:'Vous observez un hématome inexpliqué sur l\'avant-bras d\'une résidente lors de la toilette. La personne dit \'c\'est rien, un choc\'. Quelle est votre action ?', opts:['Vous acceptez l\'explication et ne notez rien', 'Vous interrogez la résidente pour savoir qui lui a fait ça', 'Vous notez factuellement (localisation, taille, aspect) et alertez l\'IDE et le cadre immédiatement', 'Vous attendez de voir si d\'autres hématomes apparaissent avant d\'agir'], rep:2, expl:'Un hématome inexpliqué est un signe d\'alerte de maltraitance. L\'AS note factuellement sans interpréter et alerte immédiatement. Il n\'interroge pas la personne (risque de la mettre en danger ou de contaminer le signalement) et ne minimise pas. La bonne foi protège le signalant légalement.' },
  { module:'Module C - Repérer et alerter', q:'L\'arrêté du 26 février 2025 étend le repérage des situations à risque à :', opts:['La personne accompagnée uniquement', 'La personne accompagnée ET les intervenants soignants', 'La personne accompagnée, les intervenants soignants ET les proches aidants', 'Uniquement les résidents en EHPAD'], rep:2, expl:'Le texte officiel de l\'arrêté est explicite : \'situations à risque pour la personne, pour les intervenants ou pour les proches aidants\'. Ce périmètre élargi inclut donc l\'épuisement de l\'aidant familial et la violence à l\'encontre des soignants — deux situations que l\'AS peut observer.' },
  { module:'Module C - Repérer et alerter', q:'Un déambulateur est prescrit à M. Dupont après une chute. Lors de la marche, vous observez qu\'il a les épaules voûtées et les coudes très fléchis. Que faites-vous ?', opts:['Vous ne faites rien — c\'est normal au début', 'Vous réglez vous-même le déambulateur à la bonne hauteur sans prévenir personne', 'Vous signalez à l\'IDE ou à l\'ergothérapeute que le déambulateur semble trop bas — réglage nécessaire', 'Vous supprimez le déambulateur car il est mal utilisé'], rep:2, expl:'L\'évaluation de l\'aide technique fait partie du rôle AS dans l\'évaluation des mesures de prévention (objectif 4 du Module C). Un déambulateur trop bas provoque une voûture et une fatigue excessive, réduisant son efficacité préventive. L\'AS signale à l\'IDE ou à l\'ergothérapeute pour réajustement.' },
  { module:'Module C - Repérer et alerter', q:'La méthode DAR utilisée dans les transmissions ciblées signifie :', opts:['Diagnostic, Action, Résultat', 'Donnée, Action, Résultat', 'Description, Alerte, Réévaluation', 'Décision, Application, Révision'], rep:1, expl:'DAR = Donnée (ce que j\'ai observé), Action (ce que j\'ai fait), Résultat (l\'effet observé). Exemple : \'Mme B. a refusé son repas (D) — j\'ai proposé de petites quantités (A) — elle a mangé un quart et signalé une douleur abdominale (R).\' Cette méthode garantit des transmissions complètes, factuelles et exploitables par l\'équipe.' },
  { module:'Module C - Repérer et alerter', q:'Évaluer les mesures de prévention mises en place (objectif 4 du Module C) signifie concrètement :', opts:['Vérifier dans le dossier que l\'IDE a bien noté la mesure', 'Observer si la mesure a produit l\'effet attendu, tracer le résultat et signaler si réajustement nécessaire', 'Attendre le bilan mensuel de l\'équipe pour en discuter', 'Demander à la personne si elle est satisfaite de la mesure'], rep:1, expl:'L\'évaluation est active et quotidienne, pas passive. L\'AS observe l\'effet de la mesure (le poids remonte-t-il ? la rougeur a-t-elle disparu après repositionnement ?) et trace cette évaluation dans le dossier. Si la mesure n\'est pas efficace ou n\'est plus adaptée, il le signale à l\'IDE pour réajustement.' },
  { module:'Module C - Repérer et alerter', q:'Dans le cadre du Module C, la bientraitance est définie comme :', opts:['L\'absence totale de maltraitance', 'Une démarche active qui se construit à chaque soin — respecter le rythme, expliquer les gestes, valoriser les capacités', 'Une formation obligatoire annuelle pour tous les soignants', 'Un outil d\'évaluation de la satisfaction des résidents'], rep:1, expl:'La bientraitance n\'est pas la simple absence de maltraitance — c\'est une posture professionnelle active. Elle se manifeste dans les gestes (frapper avant d\'entrer, expliquer chaque soin) et dans les mots (vouvoyer si c\'est le souhait, appeler par son nom). Elle est l\'opposé de la maltraitance institutionnelle.' },
  { module:'Numérique en santé', q:'Votre collègue vous demande son mot de passe DPI qu\'elle a oublié — elle en a besoin de toute urgence. Que faites-vous ?', opts:['Vous lui donnez le vôtre provisoirement pour qu\'elle puisse travailler', 'Vous refusez — chaque soignant doit utiliser ses propres identifiants et contacter l\'informatique', 'Vous lui montrez votre écran pour qu\'elle voie ce qu\'elle cherche', 'Vous notez les informations sur un papier pour elle'], rep:1, expl:'Les identifiants sont personnels et intransmissibles. Utiliser le compte d\'un autre soignant, même avec sa permission, vous rend responsable de tout ce qui est fait sous ce compte. La solution est de contacter le service informatique pour réinitialiser le mot de passe — même en urgence.' },
  { module:'Numérique en santé', q:'Lors de la toilette de M. Durand, vous observez une plaie inhabituellement grande au dos. La méthode DAR correcte dans le DPI est :', opts:['\'Plaie dans le dos\' — court et efficace', '\'Observation : plaie d\'environ 4 cm, rouge vive, au niveau de l\'omoplate gauche (D). Signalé à l\'IDE Mme Martin à 9h15 (A). IDE venue évaluer à 9h20, prise en charge prévue (R).\'', '\'Plaie suspecte — possible maltraitance\'', '\'RAS sauf plaie dos\''], rep:1, expl:'La méthode DAR exige une donnée factuelle précise (localisation, taille, aspect), l\'action réalisée (qui a été prévenu, à quelle heure), et le résultat (suite donnée). \'RAS\' ou \'plaie dos\' sont des transmissions incomplètes qui ne permettent pas d\'assurer la continuité des soins.' },
  { module:'Numérique en santé', q:'Votre glucomètre connecté affiche 0,62 g/L pour Mme Aubert mais la transmission vers le DPI a échoué. Que faites-vous ?', opts:['Vous refaites la mesure jusqu\'à ce que la transmission fonctionne', 'Vous notez manuellement la valeur avec l\'heure exacte dans le DPI et signalez le dysfonctionnement à l\'IDE', 'Vous attendez que le système se reconnecte pour saisir la valeur', 'Vous arrondissez à 0,60 pour faciliter la saisie manuelle'], rep:1, expl:'La valeur exacte (0,62 g/L) doit être tracée avec l\'heure précise de la mesure, même manuellement. Ne jamais arrondir, ne jamais attendre. Signaler le dysfonctionnement technique à l\'IDE ou au cadre. La traçabilité ne s\'arrête pas parce que l\'outil connecté ne fonctionne pas.' },
  { module:'Numérique en santé', q:'La famille de Mme Bernard vous demande de leur montrer son dossier médical pour \'voir comment elle va\'. Que répondez-vous ?', opts:['Vous leur montrez les dernières transmissions — c\'est leur mère', 'Vous refusez et les dirigez vers le médecin ou l\'IDE qui pourront répondre à leurs questions', 'Vous leur donnez accès à votre session pour qu\'ils lisent eux-mêmes', 'Vous leur lisez les dernières notes à voix haute dans le couloir'], rep:1, expl:'L\'accès au dossier médical d\'un patient est réservé aux professionnels de santé qui le prennent en charge et au patient lui-même. La famille n\'y a pas droit sans l\'accord explicite du patient (sauf cas particuliers). L\'AS redirige vers l\'IDE ou le médecin — jamais il ne montre le dossier ou le lit à voix haute, surtout dans un espace commun.' },
  { module:'Numérique en santé', q:'Le DPI est en panne depuis 30 minutes en plein milieu de votre tournée. Quelle est la bonne conduite ?', opts:['Vous attendez que le système revienne et faites les soins sans tracer', 'Vous continuez les soins, notez tout sur papier avec date et heure, prévenez l\'IDE, et saisissez dans le DPI dès le retour du système', 'Vous arrêtez votre tournée jusqu\'au rétablissement du système', 'Vous notez tout de mémoire et saisissez en fin de service'], rep:1, expl:'Une panne ne dispense pas de la traçabilité. Le mode dégradé (papier) existe précisément pour ça. On continue les soins, on note sur papier avec heure exacte, on prévient l\'IDE et le cadre, et on ressaisit dans le DPI dès qu\'il revient — avec l\'heure réelle de la mesure, pas l\'heure de saisie.' },
  { module:'Numérique en santé', q:'Vous utilisez un oxymètre de pouls sur M. Petit et la SpO2 affiche 88 %. Ses ongles sont vernis. Que faites-vous ?', opts:['Vous alertez immédiatement l\'IDE avec la valeur de 88 %', 'Vous retirez le vernis à ongles avec un dissolvant avant de remesurez', 'Vous essayez sur un autre doigt sans vernis ou sur l\'oreille, remesurez et comparez avant d\'alerter', 'Vous attendez 5 minutes et remesurez sur le même doigt'], rep:2, expl:'Le vernis à ongles (surtout foncé) peut fausser la lecture de l\'oxymètre. La bonne pratique est d\'utiliser un doigt sans vernis ou le lobe de l\'oreille. Si la valeur reste basse après une mesure fiable, alerter l\'IDE. On ne signale pas une valeur potentiellement faussée sans avoir vérifié les conditions de mesure.' },
  { module:'Numérique en santé', q:'Un email de \'la DSI de l\'établissement\' vous demande votre mot de passe DPI pour une \'mise à jour urgente de sécurité\'. Que faites-vous ?', opts:['Vous répondez avec votre mot de passe — c\'est la DSI, ils en ont besoin', 'Vous ignorez l\'email sans le signaler', 'Vous ne répondez pas et signalez immédiatement cet email au cadre ou à la DSI par téléphone direct', 'Vous changez votre mot de passe et l\'envoyez dans l\'email pour être prudent'], rep:2, expl:'Aucun service informatique légitime ne demande jamais un mot de passe par email. C\'est un phishing — une tentative d\'arnaque. La bonne conduite est de ne pas répondre et de signaler immédiatement par un autre canal (téléphone direct à la DSI, ou au cadre). Ne jamais cliquer sur les liens dans ce type d\'email.' },
  { module:'Numérique en santé', q:'Vous avez pris une photo d\'une plaie de Mme Legrand avec votre téléphone personnel pour \'mieux la décrire à l\'IDE\'. Est-ce autorisé ?', opts:['Oui — c\'est pour améliorer la prise en charge, pas pour partager', 'Oui — si vous l\'effacez après avoir montré à l\'IDE', 'Non — jamais de photo de patient avec un téléphone personnel, même à des fins soignantes', 'Oui — à condition de ne pas mettre le visage'], rep:2, expl:'Photographier un patient ou une partie de son corps avec son téléphone personnel est interdit — quelle que soit l\'intention. Les données de santé (y compris les images de plaies) sont des données ultra-sensibles soumises au RGPD. Si une photo est nécessaire pour le dossier, l\'établissement a du matériel dédié avec des protocoles spécifiques.' },
  { module:'Numérique en santé', q:'Vous notez par erreur une tension à 135/85 mmHg pour Mme Aubert alors que c\'était pour M. Bernard. Que faites-vous ?', opts:['Vous effacez la saisie et la refaites correctement', 'Vous laissez comme ça pour ne pas compliquer le dossier', 'Vous ajoutez une note corrective expliquant l\'erreur avec l\'heure et la valeur correcte, et prévenez l\'IDE', 'Vous demandez à un collègue de corriger à votre place'], rep:2, expl:'On n\'efface jamais une saisie dans un DPI — chaque modification est tracée et une suppression peut ressembler à une falsification. La bonne pratique est d\'ajouter une note corrective transparente (qui, quoi, quand, correction) et de prévenir l\'IDE. La transparence protège le soignant et le patient.' },
  { module:'Numérique en santé', q:'Dans la méthode DAR, la lettre \'A\' correspond à :', opts:['Anomalie — ce qui ne va pas chez le patient', 'Action — ce que vous avez fait suite à l\'observation', 'Alerte — qui vous avez prévenu', 'Analyse — votre interprétation de la situation'], rep:1, expl:'DAR = Donnée (ce que j\'ai observé), Action (ce que j\'ai fait), Résultat (l\'effet de mon action). La lettre A correspond à l\'action réalisée par le soignant : \'j\'ai signalé à l\'IDE\', \'j\'ai proposé une collation\', \'j\'ai repositionné\', etc. C\'est la traçabilité de votre réponse professionnelle à ce que vous avez observé.' },
  { module:'Module 02 - Repérage et prévention', q:'Un patient de 79 ans a chuté il y a 5 semaines. Il marche avec une canne. Son score de Morse est :', opts:['Forcément élevé car il a une canne', 'À calculer avec les 6 items — on ne peut pas le savoir sans les autres données', 'Toujours ≥ 45 après une chute récente', 'Nul si le médecin ne l\'a pas prescrit'], rep:1, expl:'La grille de Morse nécessite les 6 items pour être valide. Un antécédent de chute ajoute 25 pts et une canne 15 pts, mais les 4 autres items (diagnostic secondaire, perfusion, démarche, état mental) sont indispensables pour calculer le score total.' },
  { module:'Module 02 - Repérage et prévention', q:'Après une chute, l\'AS doit en priorité :', opts:['Relever immédiatement la personne pour lui éviter de rester au sol', 'Rester avec la personne, la rassurer et appeler l\'IDE avant toute mobilisation', 'Appeler la famille avant l\'IDE', 'Rédiger la FEI avant de s\'occuper du patient'], rep:1, expl:'La première priorité est de ne pas relever seul et sans évaluation. L\'AS reste au sol avec la personne, la rassure et alerte l\'IDE. La FEI est rédigée après la prise en charge.' },
  { module:'Module 02 - Repérage et prévention', q:'Vous observez une rougeur au sacrum de M. B. qui ne blanchit pas à la pression du doigt. Quel stade d\'escarre ?', opts:['Stade 2 — phlyctène', 'Stade 3 — perte de substance', 'Stade 1 — érythème persistant', 'Stade 4 — os exposé'], rep:2, expl:'Une rougeur qui ne blanchit pas à la pression est un stade 1 : la peau est encore intacte mais la circulation est compromise. C\'est le moment clé pour agir : signalement à l\'IDE et repositionnement immédiat.' },
  { module:'Module 02 - Repérage et prévention', q:'Pour prévenir l\'escarre du talon en décubitus dorsal, la bonne position est :', opts:['Coussin directement sous les talons', 'Pieds en appui sur la barrière de lit', 'Coussin sous les mollets pour que les talons soient en suspension', 'Massage des talons toutes les 2h'], rep:2, expl:'Les talons doivent être en suspension complète. Le coussin se place sous les mollets, jamais directement sous les talons. Le massage est contre-indiqué sur les zones rouges ou à risque.' },
  { module:'Module 02 - Repérage et prévention', q:'L\'AS peut décider de mettre une ceinture de fauteuil si le patient risque de glisser. Cette affirmation est :', opts:['Vraie si l\'IDE est absent et le risque immédiat', 'Fausse — toute contention nécessite une prescription médicale', 'Vraie si le patient donne son accord oral', 'Vraie pour les ceintures, fausse pour les attaches de poignets'], rep:1, expl:'Quelle que soit la forme de contention, une prescription médicale est obligatoire. L\'AS ne décide jamais seul. Il alerte l\'IDE et attend la décision médicale, même en urgence.' },
  { module:'Module 02 - Repérage et prévention', q:'Lors de la toilette, vous remarquez plusieurs hématomes à différents stades dans le dos de Mme R. Que faites-vous ?', opts:['Vous n\'en parlez pas pour ne pas créer de conflits', 'Vous interrogez la patiente sur l\'origine des hématomes', 'Vous notez précisément vos observations et alertez immédiatement l\'IDE ou le cadre', 'Vous attendez de voir si d\'autres hématomes apparaissent'], rep:2, expl:'Des hématomes à différents stades dans des zones atypiques sont un signe d\'alerte de maltraitance. L\'AS observe et note factuellement (localisation, couleur, taille) puis alerte l\'IDE ou le cadre. Il n\'interroge pas et ne promet pas de garder le secret.' },
  { module:'Module 02 - Repérage et prévention', q:'Quel numéro national permet de signaler une maltraitance de personne âgée ?', opts:['15 — SAMU', '119 — enfance en danger', '3977 — Allô Maltraitance', '17 — police secours'], rep:2, expl:'Le 3977 est le numéro national dédié à la maltraitance des personnes âgées et adultes handicapés. Tout professionnel ou particulier peut l\'appeler. Il fonctionne du lundi au vendredi de 9h à 19h.' },
  { module:'Module 02 - Repérage et prévention', q:'Mme G., 84 ans, a les muqueuses sèches, des urines très foncées et est confuse depuis ce matin. Votre première action ?', opts:['Lui donner un grand verre d\'eau et surveiller', 'Signaler immédiatement à l\'IDE ces signes de déshydratation', 'Attendre le passage médical du lendemain', 'Augmenter la fréquence des repas'], rep:1, expl:'Confusion soudaine + muqueuses sèches + urines foncées = tableau de déshydratation à signaler immédiatement à l\'IDE. L\'AS ne prend pas seul la décision de réhydrater par voie orale sans évaluation médicale si la conscience est altérée.' },
  { module:'Module 02 - Repérage et prévention', q:'Lors d\'un soin, dans quel cas le lavage au savon est-il obligatoire à la place du SHA ?', opts:['Si les mains sont froides', 'En cas de Clostridium difficile ou si les mains sont visiblement souillées', 'Toujours après un soin de nursing', 'Si le patient est en isolement contact'], rep:1, expl:'Le SHA est inefficace sur les spores de Clostridium difficile et sur le Norovirus. Dans ces cas, et si les mains sont visiblement souillées ou en sortant des toilettes, le lavage au savon est obligatoire.' },
  { module:'Module 02 - Repérage et prévention', q:'Votre formation PRAP vous aide directement dans la prévention des escarres car :', opts:['La PRAP concerne uniquement la protection de votre dos, pas les escarres', 'Les techniques de manutention sécurisées (hauteur du lit, drap de glisse) permettent de repositionner fréquemment sans blessure pour vous ni cisaillement pour le patient', 'La PRAP vous apprend à masser les zones rouges', 'Il n\'y a aucun lien entre PRAP et escarres'], rep:1, expl:'Les repositionnements toutes les 2-3h nécessaires pour prévenir les escarres doivent utiliser les techniques PRAP : lit à hauteur du bassin, drap de glisse, deux soignants si besoin. Ces techniques protègent votre dos et évitent le cisaillement cutané qui aggrave le risque d\'escarre.' },
  { module:'Module A - Anatomie/Corps', q:'Le cœur se trouve dans quelle partie du corps ?', opts:['Dans le ventre (abdomen)', 'Dans la poitrine (thorax), légèrement à gauche', 'Dans le dos, entre les omoplates', 'Dans le cou'], rep:1, expl:'Le cœur est situé dans le thorax (la poitrine), entre les deux poumons, légèrement décalé vers la gauche. C\'est lui qui pompe le sang dans tout le corps.' },
  { module:'Module A - Anatomie/Corps', q:'À quoi servent les reins ?', opts:['À digérer les aliments', 'À pomper le sang', 'À filtrer le sang et produire les urines', 'À transporter l\'oxygène'], rep:2, expl:'Les reins filtrent le sang en permanence pour éliminer les déchets, produits sous forme d\'urine. Surveiller la couleur, la quantité et l\'odeur des urines fait partie du rôle AS.' },
  { module:'Module A - Anatomie/Corps', q:'Le sacrum est une zone particulièrement surveillée car :', opts:['C\'est là où se trouve le cœur', 'C\'est une zone d\'appui majeure en position couchée sur le dos, très exposée aux escarres', 'C\'est l\'os le plus solide du corps', 'C\'est la zone où l\'on mesure la température'], rep:1, expl:'Le sacrum (base de la colonne, dans le bas du dos) est le point de pression principal en décubitus dorsal. C\'est la zone d\'escarre numéro 1 chez la personne alitée — à inspecter à chaque soin.' },
  { module:'Module A - Anatomie/Corps', q:'Les poumons permettent de :', opts:['Digérer les aliments', 'Produire les urines', 'Capter l\'oxygène de l\'air pour l\'envoyer dans le sang', 'Contrôler la température du corps'], rep:2, expl:'Les poumons captent l\'oxygène à chaque inspiration et l\'envoient dans le sang. C\'est pourquoi la saturation (SpO2) mesure le taux d\'oxygène dans le sang — si les poumons fonctionnent mal, la SpO2 baisse.' },
  { module:'Module A - Anatomie/Corps', q:'Quelle partie du corps appelle-t-on \'thorax\' ?', opts:['Le ventre', 'La poitrine (contient cœur et poumons)', 'Le dos', 'Les fesses'], rep:1, expl:'Le thorax est la partie supérieure du tronc, délimitée par les côtes. Il contient le cœur et les poumons — les deux organes vitaux que l\'AS surveille via la fréquence cardiaque, la tension et la saturation.' },
  { module:'Module A - Anatomie/Corps', q:'Les ischions sont :', opts:['Les os du crâne', 'Les \'os des fesses\' sur lesquels on s\'appuie en position assise', 'Les os du poignet', 'Les vertèbres du cou'], rep:1, expl:'Les ischions sont les os du bassin sur lesquels repose le poids du corps en position assise. Ce sont des zones d\'escarre fréquentes chez les personnes en fauteuil roulant ou peu mobiles.' },
  { module:'Module A - Anatomie/Corps', q:'La colonne vertébrale (rachis) est à respecter particulièrement chez la personne âgée car :', opts:['Elle est plus grosse qu\'un os normal', 'Elle peut être fragilisée par l\'ostéoporose — une traction brutale peut provoquer une fracture', 'Elle contrôle la respiration', 'C\'est là qu\'on mesure la glycémie'], rep:1, expl:'L\'ostéoporose rend les os poreux et fragiles. Les vertèbres peuvent se fracturer lors d\'un choc même léger ou d\'une manutention brusque. La PRAP et les techniques de mobilisation douce protègent à la fois votre dos et celui de la personne soignée.' },
  { module:'Module A - Anatomie/Corps', q:'Le glucose (sucre dans le sang) sert principalement à :', opts:['Fabriquer les urines', 'Transporter l\'oxygène', 'Fournir de l\'énergie à toutes les cellules du corps', 'Lutter contre les infections'], rep:2, expl:'Le glucose est le carburant de toutes les cellules. Quand il manque (hypoglycémie), le cerveau est le premier à en souffrir — d\'où la confusion, les tremblements, les sueurs. C\'est une urgence à traiter rapidement.' },
  { module:'Module A - Paramètres vitaux', q:'Mme Martin a une tension à 85/55 mmHg. Quelle est votre action ?', opts:['C\'est normal pour une personne âgée, je ne fais rien', 'Je lui donne à boire car elle est sûrement déshydratée', 'Je préviens l\'IDE immédiatement car c\'est une hypotension', 'Je lui fais faire des exercices pour augmenter sa tension'], rep:2, expl:'Une tension à 85/55 mmHg est une hypotension (tension basse). La limite d\'alerte est 90/60 mmHg. L\'AS prévient immédiatement l\'IDE avec la valeur mesurée, l\'heure et l\'état général de la patiente.' },
  { module:'Module A - Paramètres vitaux', q:'Un pouls à 52 bpm, régulier, chez une patiente habituellement à 70 bpm. Que faites-vous ?', opts:['Rien, c\'est dans les limites normales', 'Je le signale à l\'IDE car c\'est une bradycardie inhabituelle pour cette patiente', 'J\'attends la prochaine mesure programmée', 'Je lui donne plus à manger'], rep:1, expl:'52 bpm est dans la limite basse mais surtout c\'est inhabituel pour cette patiente (habituellement à 70). Tout écart significatif par rapport au bilan habituel doit être signalé — l\'IDE appréciera s\'il faut agir.' },
  { module:'Module A - Paramètres vitaux', q:'Lors d\'un soin, M. Dupont (diabétique) vous dit qu\'il se sent bizarre, tremble et transpire. Glycémie : 0,58 g/L. Que faites-vous en premier ?', opts:['Je termine le soin et préviens l\'IDE après', 'J\'appelle l\'IDE immédiatement — c\'est une hypoglycémie sévère', 'Je lui donne un verre de jus d\'orange sans avertir l\'IDE', 'Je mesure à nouveau la glycémie dans 30 minutes'], rep:1, expl:'0,58 g/L avec des signes cliniques = hypoglycémie sévère. C\'est une urgence. L\'AS appelle l\'IDE immédiatement. Il ne donne rien par voie orale sans ordre médical si la conscience est altérée (risque de fausse route).' },
  { module:'Module A - Paramètres vitaux', q:'Quelle valeur de SpO2 est normale pour un adulte sans pathologie respiratoire ?', opts:['≥ 95 %', '88–92 %', '80–85 %', '≥ 99 % obligatoirement'], rep:0, expl:'Une SpO2 ≥ 95 % est normale. En dessous de 95 %, c\'est un signal. Attention : en BPCO, le médecin peut prescrire une cible plus basse (88-92 %) — toujours vérifier la cible prescrite avant d\'alerter.' },
  { module:'Module A - Paramètres vitaux', q:'Mme G. souffre d\'Alzheimer et est habituellement calme. Ce matin, elle est très agitée et crie. Quelle est votre première réflexion ?', opts:['Elle fait une crise liée à sa démence, c\'est normal', 'Une agitation inhabituelle peut cacher une douleur, une infection ou un globe vésical — à signaler à l\'IDE', 'Il faut l\'isoler pour calmer les autres résidents', 'On attend que ça passe'], rep:1, expl:'Chez une personne atteinte de démence, l\'agitation inhabituelle est souvent le seul signe qu\'elle peut exprimer pour communiquer une douleur, une infection urinaire, un besoin non satisfait ou une rétention urinaire. L\'AS signale à l\'IDE pour évaluation.' },
  { module:'Module A - Paramètres vitaux', q:'Pour un résident porteur d\'une prothèse totale de hanche (PTH), quelle position est interdite ?', opts:['Position allongée sur le dos', 'Flexion de la hanche au-delà de 90° (se pencher en avant trop fort)', 'Position demi-assise à 30°', 'Jambes légèrement écartées'], rep:1, expl:'Après une PTH, la flexion de hanche au-delà de 90° risque de luxer la prothèse (la faire sortir de son logement). L\'AS veille à ce que le résident ne se penche pas trop en avant, ne croise pas les jambes et respecte les précautions prescrites.' },
  { module:'Module A - Paramètres vitaux', q:'Lors d\'une toilette, vous observez que les jambes de M. B. sont beaucoup plus gonflées que d\'habitude. Il pèse 2 kg de plus qu\'avant-hier. Vous suspectez :', opts:['Il mange trop', 'Une rétention d\'eau liée à son insuffisance cardiaque — à signaler à l\'IDE rapidement', 'Des escarres aux jambes', 'Une fracture des deux jambes'], rep:1, expl:'Prise de poids rapide (2 kg en 48h) + jambes gonflées = rétention d\'eau, signe d\'aggravation de l\'insuffisance cardiaque. L\'AS note le poids avec l\'heure et les conditions de mesure, et prévient l\'IDE dans les 2 heures.' },
  { module:'Module A - Paramètres vitaux', q:'Vous mesurez la température de Mme R. en voie axillaire (sous l\'aisselle) : 37,8°C. Sa vraie température est :', opts:['37,8°C exactement', 'Environ 38,3°C (la voie axillaire est 0,5°C en dessous de la réalité)', '37,3°C', 'Impossible à savoir'], rep:1, expl:'La voie axillaire donne une valeur environ 0,5°C inférieure à la température réelle. 37,8°C en axillaire correspond donc à environ 38,3°C — c\'est une fièvre à signaler à l\'IDE.' },
  { module:'Module A - Paramètres vitaux', q:'Comment transmettre une alerte efficacement à l\'IDE ? Vous utilisez la méthode :', opts:['URGENCE : juste dire le problème sans contexte', 'SBAR : Situation, Background, Assessment, Recommandation', 'ABCDE : Airways, Breathing, Circulation, Disability, Exposure', 'Il n\'y a pas de méthode, chacun fait comme il veut'], rep:1, expl:'La méthode SBAR structure la transmission : Situation (qui, quoi), Background (contexte médical), Assessment (ce que vous observez), Recommandation (ce que vous demandez). Elle évite les oublis et permet à l\'IDE d\'évaluer rapidement la gravité.' },
  { module:'Module A - Paramètres vitaux', q:'Une mesure de paramètre non notée dans le dossier patient :', opts:['Est valable si vous vous en souvenez', 'N\'existe pas légalement — la traçabilité est une obligation réglementaire (arrêté 2025)', 'Peut être notée le lendemain', 'Est la responsabilité de l\'IDE, pas de l\'AS'], rep:1, expl:'L\'arrêté du 26 février 2025 exige explicitement la traçabilité des données avec exactitude. Une mesure non tracée n\'a pas d\'existence légale et ne peut pas servir à suivre l\'évolution de l\'état du patient. Chaque mesure = date, heure, valeur, signature.' },
];
